package com.rikkeibank.transaction.model;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="transaction_entries") public class TransactionEntry{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false) private Long transactionId;@Column(nullable=false) private Long accountId;@Column(nullable=false) private String entryType;@Column(nullable=false,precision=19,scale=2) private BigDecimal amount;public Long getId(){return id;}public Long getTransactionId(){return transactionId;}public void setTransactionId(Long v){transactionId=v;}public Long getAccountId(){return accountId;}public void setAccountId(Long v){accountId=v;}public String getEntryType(){return entryType;}public void setEntryType(String v){entryType=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}}
